    13	class AppPropertiesTest {
    14	
    15	    @Test
    16	    void should_bindAllNestedProperties_when_sourceContainsAppPrefix() {
    17	        Map<String, String> source = Map.of(
    18	                "app.data-init.enabled", "true",
    19	                "app.security.jwt.secret", "0123456789012345678901234567890123",
    20	                "app.security.jwt.access-token-validity", "PT15M",
    21	                "app.security.jwt.refresh-token-validity", "P7D",
    22	                "app.security.admin.enabled", "true",
    23	                "app.security.admin.phone-number", "+420000000000",
    24	                "app.security.admin.name", "Administrator",
    25	                "app.security.admin.password", "admin");
    26	
    27	        AppProperties props = new Binder(new MapConfigurationPropertySource(source))
    28	                .bind("app", Bindable.of(AppProperties.class))
    29	                .get();
    30	
    31	        assertThat(props.dataInit().enabled()).isTrue();
    32	        assertThat(props.security().jwt().secret()).isEqualTo("0123456789012345678901234567890123");
    33	        assertThat(props.security().jwt().accessTokenValidity()).isEqualTo(Duration.ofMinutes(15));
    34	        assertThat(props.security().jwt().refreshTokenValidity()).isEqualTo(Duration.ofDays(7));
    35	        assertThat(props.security().admin().enabled()).isTrue();
    36	        assertThat(props.security().admin().phoneNumber()).isEqualTo("+420000000000");
    37	        assertThat(props.security().admin().name()).isEqualTo("Administrator");
    38	        assertThat(props.security().admin().password()).isEqualTo("admin");
    39	    }
    40	
    41	    @Test
    42	    void should_defaultAdminEnabledToFalseAndLeaveDataInitNull_when_notProvided() {
    43	        Map<String, String> source = Map.of(
    44	                "app.security.jwt.secret", "s",
    45	                "app.security.jwt.access-token-validity", "PT1M",
    46	                "app.security.jwt.refresh-token-validity", "PT2M",
    47	                "app.security.admin.phone-number", "+1",
    48	                "app.security.admin.name", "n",
    49	                "app.security.admin.password", "p");
    50	
    51	        AppProperties props = new Binder(new MapConfigurationPropertySource(source))
    52	                .bind("app", Bindable.of(AppProperties.class))
    53	                .get();
    54	
    55	        assertThat(props.dataInit()).as("nested record without any bound property stays null").isNull();
    56	        assertThat(props.security().admin().enabled()).isFalse();
    57	    }
    58	}
